#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> p, r;
    vector<long long> diff; 
    // diff[x] = value(x) - value(parent[x])
    // Here value(unit) is its exponent relative to component root.

    DSU(int n = 0) { init(n); }

    void init(int n) {
        p.resize(n);
        r.assign(n, 0);
        diff.assign(n, 0);
        iota(p.begin(), p.end(), 0);
    }

    pair<int, long long> find(int x) {
        if (p[x] == x) return {x, 0};
        auto res = find(p[x]);
        diff[x] += res.second;
        p[x] = res.first;
        return {p[x], diff[x]};
    }

    // Enforce: value(a) - value(b) = w
    // Returns false if contradiction appears.
    bool unite(int a, int b, long long w) {
        auto fa = find(a);
        auto fb = find(b);

        int ra = fa.first, rb = fb.first;
        long long da = fa.second, db = fb.second;

        if (ra == rb) {
            return (da - db == w);
        }

        if (r[ra] < r[rb]) {
            swap(ra, rb);
            swap(da, db);
            w = -w;
        }

        p[rb] = ra;
        // Need: (da) - (db + diff[rb]) = w
        // => diff[rb] = da - db - w
        diff[rb] = da - db - w;

        if (r[ra] == r[rb]) r[ra]++;
        return true;
    }
};

