#define MAX_UNITS 200
#define MAX_NAME 20

typedef struct {
    char name[MAX_NAME];
    int id;
} Unit;

Unit units[MAX_UNITS];
int unit_count = 0;
int dist[MAX_UNITS][MAX_UNITS];
int visited[MAX_UNITS][MAX_UNITS];

int get_id(char *name) {
    for (int i = 0; i < unit_count; i++) {
        if (strcmp(units[i].name, name) == 0)
            return i;
    }
    strcpy(units[unit_count].name, name);
    units[unit_count].id = unit_count;
    unit_count++;
    return unit_count - 1;
}

int main() {
    int n;
    scanf("%d", &n);

    // Initialize distance matrix with a large sentinel (-1 means unknown)
    for (int i = 0; i < MAX_UNITS; i++)
        for (int j = 0; j < MAX_UNITS; j++)
            dist[i][j] = -1;

    for (int i = 0; i < MAX_UNITS; i++)
        dist[i][i] = 0;

    int contradictory = 0;

    for (int i = 0; i < n; i++) {
        char a_name[MAX_NAME], b_name[MAX_NAME], eq[MAX_NAME];
        int pow10;
        scanf("%s %s %s %d %s", a_name, eq, eq, &pow10, b_name);

        if (strcmp(eq, "=") != 0) {
            // skip malformed input, but problem guarantees format
        }

        int a = get_id(a_name);
        int b = get_id(b_name);

        if (dist[a][b] != -1 && dist[a][b] != pow10) {
            contradictory = 1;
            break;
        }

        dist[a][b] = pow10;
        dist[b][a] = -pow10; // inverse relation

        // Floyd-Warshall style propagation for consistency
        for (int k = 0; k < unit_count; k++) {
            for (int i = 0; i < unit_count; i++) {
                if (dist[i][k] == -1) continue;
                for (int j = 0; j < unit_count; j++) {
                    if (dist[k][j] == -1) continue;
                    int new_dist = dist[i][k] + dist[k][j];
                    if (dist[i][j] == -1) {
                        dist[i][j] = new_dist;
                        dist[j][i] = -new_dist;
                    } else if (dist[i][j] != new_dist) {
                        contradictory = 1;
                        break;
                    }
                }
                if (contradictory) break;
            }
            if (contradictory) break;
        }
        if (contradictory) break;
    }

    printf("%s\n", contradictory ? "contradictory" : "consistent");
    return 0;
}

