int parent[MAXN];
long long weight[MAXN]; // weight[i]: value(i) = 10^weight[i] * value(root(i))
int n_units;
char units[MAXN][50];

int get_id(char *name) {
    for (int i = 0; i < n_units; i++)
        if (strcmp(units[i], name) == 0) return i;
    strcpy(units[n_units], name);
    parent[n_units] = n_units;
    weight[n_units] = 0;
    return n_units++;
}

int find(int x, long long *w) {
    if (parent[x] == x) { *w = 0; return x; }
    long long pw;
    int root = find(parent[x], &pw);
    *w = weight[x] + pw;
    parent[x] = root;
    weight[x] = *w;
    return root;
}

