#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 200005
#define MAXM 400005
#define NAME_LEN 64
#define TABLE_SIZE 524287

typedef long long ll;

typedef struct {
    int to;
    ll w;
    int next;
} Edge;

typedef struct {
    char name[NAME_LEN];
    int id;
    int used;
} HashEntry;

static Edge edges[MAXM];
static int head[MAXN];
static int edgeCnt = 0;

static HashEntry table[TABLE_SIZE];
static int nodeCnt = 0;

static ll value[MAXN];
static int vis[MAXN];

unsigned long long hash_str(const char *s) {
    unsigned long long h = 1469598103934665603ULL;
    while (*s) {
        h ^= (unsigned char)(*s++);
        h *= 1099511628211ULL;
    }
    return h;
}

int get_id(const char *s) {
    unsigned long long h = hash_str(s) % TABLE_SIZE;
    while (table[h].used) {
        if (strcmp(table[h].name, s) == 0) return table[h].id;
        h++;
        if (h == TABLE_SIZE) h = 0;
    }
    table[h].used = 1;
    strcpy(table[h].name, s);
    table[h].id = nodeCnt;
    return nodeCnt++;
}

void add_edge(int u, int v, ll w) {
    edges[edgeCnt].to = v;
    edges[edgeCnt].w = w;
    edges[edgeCnt].next = head[u];
    head[u] = edgeCnt++;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < MAXN; i++) head[i] = -1;

    for (int i = 0; i < n; i++) {
        char a[NAME_LEN], b[NAME_LEN];
        ll x;
        if (scanf("%s %lld %s", a, &x, b) != 3) return 0;

        int u = get_id(a);
        int v = get_id(b);

        /* 1 A = 10^x B
           Let val[node] be exponent relative to component root.
           Then A - B = x, so:
           B = A - x
        */
        add_edge(u, v, -x);
        add_edge(v, u, x);
    }

    int *queue = (int *)malloc(sizeof(int) * nodeCnt);
    int contradiction = 0;

    for (int s = 0; s < nodeCnt && !contradiction; s++) {
        if (vis[s]) continue;

        int front = 0, back = 0;
        queue[back++] = s;
        vis[s] = 1;
        value[s] = 0;

        while (front < back && !contradiction) {
            int u = queue[front++];
            for (int e = head[u]; e != -1; e = edges[e].next) {
                int v = edges[e].to;
                ll expected = value[u] + edges[e].w;
                if (!vis[v]) {
                    vis[v] = 1;
                    value[v] = expected;
                    queue[back++] = v;
                } else if (value[v] != expected) {
                    contradiction = 1;
                    break;
                }
            }
        }
    }

    free(queue);

    printf("%s\n", contradiction ? "contradictory" : "consistent");
    return 0;
}

