public class Main {
    static Map<String, Map<String, Long>> graph = new HashMap<>();
    static Map<String, Map<String, Long>> rel = new HashMap<>();

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        boolean consistent = true;

        for (int i = 0; i < n; i++) {
            String line = sc.nextLine().trim();
            String[] parts = line.split(" ");
            // format: 1 A = 10^x B
            String unitA = parts[1];
            String unitB = parts[4];
            String powStr = parts[3].substring(2); // remove "10^"
            long power = Long.parseLong(powStr);

            if (!graph.containsKey(unitA)) graph.put(unitA, new HashMap<>());
            if (!graph.containsKey(unitB)) graph.put(unitB, new HashMap<>());

            // check if relation already defined
            if (rel.containsKey(unitA) && rel.get(unitA).containsKey(unitB)) {
                long existing = rel.get(unitA).get(unitB);
                if (existing != power) {
                    consistent = false;
                }
            } else {
                rel.computeIfAbsent(unitA, k -> new HashMap<>()).put(unitB, power);
                rel.computeIfAbsent(unitB, k -> new HashMap<>()).put(unitA, -power);
                graph.get(unitA).put(unitB, power);
                graph.get(unitB).put(unitA, -power);
            }
        }

        // check consistency by BFS from each node
        for (String start : graph.keySet()) {
            if (!consistent) break;
            Map<String, Long> dist = new HashMap<>();
            Queue<String> q = new LinkedList<>();
            dist.put(start, 0L);
            q.add(start);
            while (!q.isEmpty() && consistent) {
                String u = q.poll();
                long du = dist.get(u);
                for (Map.Entry<String, Long> e : graph.getOrDefault(u, new HashMap<>()).entrySet()) {
                    String v = e.getKey();
                    long w = e.getValue();
                    if (!dist.containsKey(v)) {
                        dist.put(v, du + w);
                        q.add(v);
                    } else {
                        if (dist.get(v) != du + w) {
                            consistent = false;
                            break;
                        }
                    }
                }
            }
        }

        System.out.println(consistent ? "consistent" : "contradictory");
    }
}

import java.util.*;

public class Main {
    static Map<String, String> parent = new HashMap<>();
    static Map<String, Integer> offset = new HashMap<>(); // offset[x] = log10(x) - log10(root(x))

    static String find(String x) {
        if (!parent.containsKey(x)) { parent.put(x, x); offset.put(x, 0); }
        if (parent.get(x).equals(x)) return x;
        String root = find(parent.get(x));
        offset.put(x, offset.get(x) + offset.get(parent.get(x)));
        parent.put(x, root);
        return root;
    }

    static boolean union(String a, String b, int x) {
        // a = 10^x * b
        String ra = find(a), rb = find(b);
        int oa = offset.get(a), ob = offset.get(b);
        if (ra.equals(rb)) {
            return (oa - ob) == x;
        }
        // offset[rb] = oa - x - ob
        parent.put(rb, ra);
        offset.put(rb, oa - x - ob);
        return true;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        boolean consistent = true;
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) continue;
            // parse: "1 A = 10^x B"
            String[] parts = line.split("\\s+");
            // parts: "1", A, "=", "10^x", B
            String A = parts[1], B = parts[4];
            int x = Integer.parseInt(parts[3].substring(3)); // "10^x" -> x
            if (!union(A, B, x)) consistent = false;
        }
        System.out.println(consistent ? "consistent" : "contradictory");
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static class WeightedDSU {
        int[] parent;
        int[] rank;
        long[] diff; 
        // diff[x] = value(x) - value(parent[x])

        WeightedDSU(int n) {
            parent = new int[n];
            rank = new int[n];
            diff = new long[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }

        int find(int x) {
            if (parent[x] == x) return x;
            int p = parent[x];
            int r = find(p);
            diff[x] += diff[p];
            return parent[x] = r;
        }

        long weightToRoot(int x) {
            find(x);
            return diff[x];
        }

        // Enforce: value(a) - value(b) = w
        boolean unite(int a, int b, long w) {
            int ra = find(a);
            int rb = find(b);
            long wa = diff[a];
            long wb = diff[b];

            if (ra == rb) {
                return (wa - wb) == w;
            }

            if (rank[ra] < rank[rb]) {
                parent[ra] = rb;
                // Need: (wa + diffRootAtoB) - wb = w
                // so diffRootAtoB = w - wa + wb
                diff[ra] = w - wa + wb;
            } else {
                parent[rb] = ra;
                // Need: wa - (wb + diffRootBtoA) = w
                // so diffRootBtoA = wa - wb - w
                diff[rb] = wa - wb - w;
                if (rank[ra] == rank[rb]) rank[ra]++;
            }
            return true;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        String first = fs.next();
        if (first == null) return;

        int m = Integer.parseInt(first);

        Map<String, Integer> id = new HashMap<>();
        List<String[]> relations = new ArrayList<>();
        List<Long> powers = new ArrayList<>();

        for (int i = 0; i < m; i++) {
            String one = fs.next();      // "1"
            String A = fs.next();        // unit A
            String eq = fs.next();       // "="
            String tenPow = fs.next();   // like 10^x
            String B = fs.next();        // unit B

            if (!id.containsKey(A)) id.put(A, id.size());
            if (!id.containsKey(B)) id.put(B, id.size());

            long x;
            int pos = tenPow.indexOf('^');
            if (pos >= 0) x = Long.parseLong(tenPow.substring(pos + 1));
            else x = Long.parseLong(tenPow); // fallback if input is just x

            relations.add(new String[]{A, B});
            powers.add(x);
        }

        WeightedDSU dsu = new WeightedDSU(id.size());
        boolean ok = true;

        for (int i = 0; i < relations.size(); i++) {
            String A = relations.get(i)[0];
            String B = relations.get(i)[1];
            long x = powers.get(i);

            int a = id.get(A);
            int b = id.get(B);

            // 1 A = 10^x B
            // Let value(unit) be exponent relative to some root scale.
            // Then value(A) - value(B) = x
            if (!dsu.unite(a, b, x)) {
                ok = false;
                break;
            }
        }

        System.out.println(ok ? "consistent" : "contradictory");
    }
}

import sys
from collections import defaultdict, deque

def solve(relations):
    offset = {}  # unit -> integer offset
    adj = defaultdict(list)  # unit -> [(neighbor, weight)]

    for (a, x, b) in relations:
        # offset[a] - offset[b] = x
        adj[a].append((b, x))
        adj[b].append((a, -x))

    # BFS to assign offsets
    for start in list(adj.keys()):
        if start not in offset:
            offset[start] = 0
            queue = deque([start])
            while queue:
                node = queue.popleft()
                for (neighbor, w) in adj[node]:
                    expected = offset[node] - w
                    if neighbor not in offset:
                        offset[neighbor] = expected
                        queue.append(neighbor)
                    else:
                        if offset[neighbor] != expected:
                            return "contradiction"
    return "consistent"

